def build_max_window_v30(name, title, color, tools):
    win = build_editor_window(name, title, color, tools[:60])
    for c in win.children:
        if c.name=="Header":
            for t in c.children:
                if t.name=="Title":
                    t.props["Text"]=(T_STRING, f"{title} • {len(tools)} TOOLS")
    for c in win.children:
        if c.name=="Tools":
            rows = (len(tools)+2)//3
            h = rows*36 + 20
            c.props["CanvasSize"]=(T_UDIM2, udim2(0,0,0,h))
            if len(tools)>60:
                for t in tools[60:]:
                    btn = Inst("TextButton", t.replace(" ","_"), {"BackgroundColor3":(T_COLOR3, col(CYBER["panelAlt"])),"BorderSizePixel":(T_INT,0),"Text":(T_STRING, t),"TextColor3":(T_COLOR3, col(CYBER["text"])),"TextSize":(T_FLOAT32,10),"Font":(T_ENUM,2),"AutoButtonColor":(T_BOOL,True)})
                    btn.add(Inst("UICorner","C",{"CornerRadius":(T_UDIM, udim(0,6))}))
                    ic = Inst("Frame","Icon",{"BackgroundTransparency":(T_FLOAT32,1),"Size":(T_UDIM2, udim2(0,14,0,14)),"Position":(T_UDIM2, udim2(0,4,0.5,0)),"AnchorPoint":(T_VECTOR2, vec2(0,0.5)),"BorderSizePixel":(T_INT,0)})
                    ic.add(Inst("ImageLabel","Img",{"BackgroundTransparency":(T_FLOAT32,1),"Size":(T_UDIM2, udim2(1,0,1,0)),"Image":(T_STRING,f"rbxassetid://6031091000"),"BorderSizePixel":(T_INT,0)}))
                    btn.add(ic)
                    c.add(btn)
            break
    return win

def patch30(roots):
    for r in roots:
        if r.cls=="StarterGui":
            for sg in r.children:
                if sg.name=="ARKHER_STUDIO":
                    for child in sg.children:
                        if child.name=="Root":
                            ex={c.name for c in child.children}
                            for name,title,color,tools in EDITORS_V30:
                                if name not in ex:
                                    child.add(build_max_window_v30(name,title,color,tools))
    FUNC30 = """
local P=game:GetService("Players") local pl=P.LocalPlayer
local function call(pat,name)
 local e=_G.ARKHER if not e then print("[TOOL30] "..name.." offline") return end
 local f=e:findSystems(pat) if #f==0 then f=e:findSystems(string.lower(name)) end
 if #f>0 then local en=f[1] local ok=pcall(function() if en.instance.selfTest then return en.instance.selfTest() end return true end) print(string.format("[TOOL30] %s -> %s ok=%s",name,en.key,tostring(ok)))
  local g=pl.PlayerGui:FindFirstChild("ARKHER_STUDIO") if g then local s=g.Root:FindFirstChild("StatusBar",true) if s then local l=s:FindFirstChild("Cmd") if l then l.Text=name.." -> "..en.key end end end
 else print("[TOOL30] "..name.." no "..pat) end
end
local MAP30={ARKHER_LightingAAA="f",ARKHER_ShadowAAA="f",ARKHER_GI_AAA="f",ARKHER_ReflectionAAA="f",ARKHER_FoliageAAA="c",ARKHER_WaterAAA="c",ARKHER_CloudAAA="f",ARKHER_QuestAAA="p",ARKHER_DialogueAAA="p",ARKHER_CutsceneAAA="w",ARKHER_NPC_AAA="k",ARKHER_MultiplayerAAA="r",ARKHER_TelemetryAAA="telemetry",ARKHER_PublishingAAA="publishing"}
local function wire30(name)
 local g=pl.PlayerGui:FindFirstChild("ARKHER_STUDIO") if not g then return end
 local w=g.Root:FindFirstChild(name,true) if not w then return end
 local c=w:FindFirstChild("Tools",true) or w
 for _,b in ipairs(c:GetDescendants()) do if b:IsA("TextButton") then b.Activated:Connect(function()
  local o=b.BackgroundColor3 b.BackgroundColor3=Color3.fromRGB(255,214,0) task.delay(0.2,function() b.BackgroundColor3=o end)
  local cat=MAP30[name] or "" local pat=cat~="" and ("arkher."..cat.."."..string.lower(b.Name)) or string.lower(b.Name)
  call(pat,b.Name)
 end) end end
end
for _,n in ipairs({"ARKHER_LightingAAA","ARKHER_ShadowAAA","ARKHER_GI_AAA","ARKHER_ReflectionAAA","ARKHER_FoliageAAA","ARKHER_WaterAAA","ARKHER_CloudAAA","ARKHER_QuestAAA","ARKHER_DialogueAAA","ARKHER_CutsceneAAA","ARKHER_NPC_AAA","ARKHER_MultiplayerAAA","ARKHER_TelemetryAAA","ARKHER_PublishingAAA"}) do pcall(wire30,n) end
print("[V1.30 MAX] +14 editores finais — 331 editores, AAA console/PC no celular 100%")
"""
    for r in roots:
        if r.cls=="StarterPlayer":
            for f in r.children:
                if f.name=="StarterPlayerScripts":
                    f.add(Inst("LocalScript","ARKHER_ToolsFunctional_V30",{"Source":(T_STRING, FUNC30)}))
    return roots

